  // Return the maximum water area between two lines.
  return 0;
}

solution:
function MaxArea(height: int[]) -> int {
  let lo = 0;
  let hi = height.length() - 1;
  let best = 0;
  while (lo < hi) {
    let h = height[lo];
    let h2 = height[hi];
    let minh = h;
    if (h2 < h) {
      minh = h2;
    }
    let area = minh * (hi - lo);
    if (area > best) {
      best = area;
    }
    if (h < h2) {
      lo += 1;
    } else {
      hi -= 1;
    }
  }
  return best;
}
